import{_ as t,o as r,c as a,ag as i}from"./chunks/framework.B61-P76f.js";const u=JSON.parse('{"title":"index","description":"","frontmatter":{},"headers":[],"relativePath":"reference/index/index.md","filePath":"reference/index/index.md"}'),d={name:"reference/index/index.md"};function o(n,e,s,l,c,h){return r(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="index" tabindex="-1">index <a class="header-anchor" href="#index" aria-label="Permalink to &quot;index&quot;">​</a></h1><h2 id="interfaces" tabindex="-1">Interfaces <a class="header-anchor" href="#interfaces" aria-label="Permalink to &quot;Interfaces&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Interface</th><th>Description</th></tr></thead><tbody><tr><td><a href="./interfaces/CdnOperation.html">CdnOperation</a></td><td>A single CDN URL directive: <code>-/name/param1/param2/</code>.</td></tr><tr><td><a href="./interfaces/FileUrlInput.html">FileUrlInput</a></td><td>Input shape for building a file url with <code>serializeCdnUrl</code>.</td></tr><tr><td><a href="./interfaces/GroupId.html">GroupId</a></td><td>File group id: <code>uuid~count</code>.</td></tr><tr><td><a href="./interfaces/GroupUrlInput.html">GroupUrlInput</a></td><td>Input shape for building a group root or group element url.</td></tr><tr><td><a href="./interfaces/NamedOperationCreator.html">NamedOperationCreator</a></td><td>Brand carried by every operation creator: the CDN directive name it produces. Lets creators themselves act as <a href="./type-aliases/OperationRef.html">OperationRef</a>s — <code>url.without(resize)</code> instead of <code>url.without(&#39;resize&#39;)</code>.</td></tr><tr><td><a href="./interfaces/ParsedArchiveUrl.html">ParsedArchiveUrl</a></td><td>A group archive URL: <code>/:uuid~N/archive/:format/(:filename)</code>. Archives hold the original files, so it carries no operations.</td></tr><tr><td><a href="./interfaces/ParsedFileUrl.html">ParsedFileUrl</a></td><td>A single-file CDN URL: <code>/:uuid/(:conversion/)(-/op/.../)(:filename)</code>.</td></tr><tr><td><a href="./interfaces/ParsedGroupElementUrl.html">ParsedGroupElementUrl</a></td><td>A group element URL: <code>/:uuid~N/nth/i/(-/op/.../)(:filename)</code>.</td></tr><tr><td><a href="./interfaces/ParsedGroupUrl.html">ParsedGroupUrl</a></td><td>A group root URL: <code>/:uuid~N/</code>. Group roots cannot carry operations or a filename — process individual files via <a href="./interfaces/ParsedGroupElementUrl.html">ParsedGroupElementUrl</a>.</td></tr><tr><td><a href="./interfaces/ParsedProxyUrl.html">ParsedProxyUrl</a></td><td>A delivery proxy URL: <code>/(-/op/.../):sourceUrl</code>. The embedded source keeps its own query string and fragment, so the shape has no <code>search</code>/<code>hash</code>.</td></tr><tr><td><a href="./interfaces/ProxyUrlInput.html">ProxyUrlInput</a></td><td>Input shape for building a delivery proxy url.</td></tr><tr><td><a href="./interfaces/TinyFileUrl.html">TinyFileUrl</a></td><td>A single-file CDN url cut into the strings <a href="./functions/tinyBuild.html">tinyBuild</a> joins back together. Only <code>cdnBase</code> and <code>uuid</code> are required; the rest default to empty, so a bare url is <code>{ cdnBase, uuid }</code>. The field names match <code>ParsedFileUrl</code>, with <code>modifiers</code> standing in for its <code>operations</code>.</td></tr></tbody></table><h2 id="type-aliases" tabindex="-1">Type Aliases <a class="header-anchor" href="#type-aliases" aria-label="Permalink to &quot;Type Aliases&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Type Alias</th><th>Description</th></tr></thead><tbody><tr><td><a href="./type-aliases/CdnUrlInput.html">CdnUrlInput</a></td><td>Input for <code>serializeCdnUrl</code> — discriminated by which addressing field is present (<code>uuid</code>, <code>group</code> or <code>sourceUrl</code>). Every <a href="./type-aliases/ParsedCdnUrl.html">ParsedCdnUrl</a> is a valid input, which is what makes parse → edit → serialize round-trips work.</td></tr><tr><td><a href="./type-aliases/CdnUrlKind.html">CdnUrlKind</a></td><td>Discriminant of <a href="./type-aliases/ParsedCdnUrl.html">ParsedCdnUrl</a>.</td></tr><tr><td><a href="./type-aliases/ConversionKind.html">ConversionKind</a></td><td>Conversion path prefixes that attach directly after the uuid with a plain <code>/</code> (no <code>-/</code> separator): <code>/:uuid/video/...</code>, <code>/:uuid/document/...</code>, <code>/:uuid/gif2video/...</code>.</td></tr><tr><td><a href="./type-aliases/CropAlignment.html">CropAlignment</a></td><td>Alignment keywords accepted where a crop offset may be given.</td></tr><tr><td><a href="./type-aliases/DomainKind.html">DomainKind</a></td><td>CDN domain classification.</td></tr><tr><td><a href="./type-aliases/ModifiersChain.html">ModifiersChain</a></td><td>A <code>-/name/params/</code> directive chain, <strong>nominally</strong> typed: a plain string at run time, but assignable only from a value this module produced — <code>modifiers()</code>, <a href="./functions/normalizeModifiers.html">normalizeModifiers</a>, <code>joinModifiers()</code> or <code>tinyParse</code>.</td></tr><tr><td><a href="./type-aliases/OperationLiteral.html">OperationLiteral</a></td><td>Operations as <strong>typed string literals</strong>, for callers whose only need is to write a modifiers chain they author themselves.</td></tr><tr><td><a href="./type-aliases/OperationRef.html">OperationRef</a></td><td>Anything that identifies an operation: its name as a string, an operation object, or the creator function itself.</td></tr><tr><td><a href="./type-aliases/ParsedCdnUrl.html">ParsedCdnUrl</a></td><td>A CDN URL decomposed into a plain serializable shape, discriminated by <a href="./type-aliases/CdnUrlKind.html">CdnUrlKind</a>. Produced by <code>parseCdnUrl</code>, consumed by <code>serializeCdnUrl</code>.</td></tr></tbody></table><h2 id="variables" tabindex="-1">Variables <a class="header-anchor" href="#variables" aria-label="Permalink to &quot;Variables&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Variable</th><th>Description</th></tr></thead><tbody><tr><td><a href="./variables/LEGACY_CDN_BASE.html">LEGACY_CDN_BASE</a></td><td>The legacy shared CDN base. It serves any project&#39;s files unprefixed, which is why it is the only safe fallback — but new projects should deliver from their own prefixed host — see <code>prefixedCdnBase</code> — rather than reach for this.</td></tr><tr><td><a href="./variables/PREFIX_CDN_BASE.html">PREFIX_CDN_BASE</a></td><td>The zone a project prefix is prepended to: <code>&lt;prefix&gt;.ucarecd.net</code>, which is what <a href="./../cdn-base/functions/prefixedCdnBase.html">cdn-base!prefixedCdnBase</a> computes. Not a typo for <code>ucarecdn.com</code> — it is the separate zone that serves per-project prefixed hostnames, and it only answers <strong>with</strong> a prefix, never bare.</td></tr></tbody></table><h2 id="functions" tabindex="-1">Functions <a class="header-anchor" href="#functions" aria-label="Permalink to &quot;Functions&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Function</th><th>Description</th></tr></thead><tbody><tr><td><a href="./functions/detectDomainKind.html">detectDomainKind</a></td><td>Classifies a CDN host: - <code>legacy</code> — <code>ucarecdn.com</code> (and its environment subdomains) - <code>prefixed</code> — project-prefixed <code>*.ucarecd.net</code> - <code>proxy</code> — delivery proxy <code>*.ucr.io</code> - <code>custom</code> — anything else (user CNAME)</td></tr><tr><td><a href="./functions/isArchiveUrl.html">isArchiveUrl</a></td><td>Whether a string is a group archive URL, without parsing it or throwing.</td></tr><tr><td><a href="./functions/isFileUrl.html">isFileUrl</a></td><td>Whether a string is a single-file CDN URL, without parsing it or throwing. Pair with <a href="./functions/parseFileUrl.html">parseFileUrl</a> when the input is untrusted.</td></tr><tr><td><a href="./functions/isGroupElementUrl.html">isGroupElementUrl</a></td><td>Whether a string is a group element URL, without parsing it or throwing.</td></tr><tr><td><a href="./functions/isGroupUrl.html">isGroupUrl</a></td><td>Whether a string is a group root URL, without parsing it or throwing.</td></tr><tr><td><a href="./functions/isProxyUrl.html">isProxyUrl</a></td><td>Whether a string is a delivery proxy URL, without parsing it or throwing. Distinct from <code>isProxyEndpoint</code>, which only inspects the host.</td></tr><tr><td><a href="./functions/isUploadcareDomain.html">isUploadcareDomain</a></td><td>Whether the host is operated by Uploadcare (not a custom CNAME).</td></tr><tr><td><a href="./functions/joinModifiers.html">joinModifiers</a></td><td>Concatenates chains — the branded stand-in for <code>`${a}${b}`</code>, which would widen back to <code>string</code>. Order is preserved, so this is how you append to a chain you already have.</td></tr><tr><td><a href="./functions/modifiers.html">modifiers</a></td><td>Joins typed operation literals into a <a href="./type-aliases/ModifiersChain.html">ModifiersChain</a> — the whole runtime cost of this module.</td></tr><tr><td><a href="./functions/normalizeModifiers.html">normalizeModifiers</a></td><td>Normalizes a modifiers string of any shape into a <a href="./type-aliases/ModifiersChain.html">ModifiersChain</a> — the string-level counterpart of <code>parseOperations</code>, and the way a value that did not come from <code>modifiers()</code> becomes a chain.</td></tr><tr><td><a href="./functions/operationBaseName.html">operationBaseName</a></td><td>Resolves an <a href="./type-aliases/OperationRef.html">OperationRef</a> to its directive name with any counted suffix stripped — <code>thumbs~5</code> and <code>thumbs~3</code> both reduce to <code>thumbs</code>.</td></tr><tr><td><a href="./functions/operationMatches.html">operationMatches</a></td><td>Whether an operation matches a ref, comparing base names so that counted suffixes line up in both directions: <code>thumbs~5</code> matches the <code>thumbs</code> ref, the <code>thumbs</code> operation matches a <code>thumbs~5</code> ref, and <code>thumbs~5</code> matches <code>thumbs~3</code>.</td></tr><tr><td><a href="./functions/operationNameOf.html">operationNameOf</a></td><td>Resolves an <a href="./type-aliases/OperationRef.html">OperationRef</a> to the operation name it identifies.</td></tr><tr><td><a href="./functions/parseArchiveUrl.html">parseArchiveUrl</a></td><td>Parses a group archive URL (<code>/:uuid~N/archive/:format/(:filename)</code>), the read-side counterpart of <code>archiveUrl</code>.</td></tr><tr><td><a href="./functions/parseCdnUrl.html">parseCdnUrl</a></td><td>Parses any Uploadcare CDN URL — file, group, group element, conversion result or proxified remote source — into a <a href="./type-aliases/ParsedCdnUrl.html">ParsedCdnUrl</a> discriminated by <code>kind</code>.</td></tr><tr><td><a href="./functions/parseFileUrl.html">parseFileUrl</a></td><td>Parses a single-file URL, including conversion results. Narrower than <a href="./functions/parseCdnUrl.html">parseCdnUrl</a>: importing this alone keeps the group and proxy parsers out of your bundle, and the result is already narrowed to <a href="./interfaces/ParsedFileUrl.html">ParsedFileUrl</a> without a <code>kind</code> check.</td></tr><tr><td><a href="./functions/parseGroupElementUrl.html">parseGroupElementUrl</a></td><td>Parses a group element URL (<code>/:uuid~N/nth/i/</code>). Narrower than <a href="./functions/parseCdnUrl.html">parseCdnUrl</a>, and distinct from <a href="./functions/parseGroupUrl.html">parseGroupUrl</a>, which handles the group root.</td></tr><tr><td><a href="./functions/parseGroupUrl.html">parseGroupUrl</a></td><td>Parses a group root URL (<code>/:uuid~N/</code>). Group roots carry no operations and no filename, which is why the returned shape has neither.</td></tr><tr><td><a href="./functions/parseOperations.html">parseOperations</a></td><td>Parses a bare modifiers string (e.g. the <code>cdnUrlModifiers</code> value stored alongside a uuid) into operations. Lenient like <a href="./functions/parseCdnUrl.html">parseCdnUrl</a>; round-trips with <code>serializeOperations</code>.</td></tr><tr><td><a href="./functions/parseProxyUrl.html">parseProxyUrl</a></td><td>Parses a delivery proxy URL. Narrower than <a href="./functions/parseCdnUrl.html">parseCdnUrl</a>: importing this alone leaves the file and group parsers out of your bundle.</td></tr><tr><td><a href="./functions/serializeCdnUrl.html">serializeCdnUrl</a></td><td>Builds a CDN URL string from a <a href="./type-aliases/CdnUrlInput.html">CdnUrlInput</a>, discriminated by which addressing field is present: <code>sourceUrl</code> (proxy), <code>group</code> (group root or, with <code>nth</code>, a group element) or <code>uuid</code> (file). The counterpart of <code>parseCdnUrl</code>: <code>serializeCdnUrl(parseCdnUrl(url)) === url</code>.</td></tr><tr><td><a href="./functions/serializeFileUrl.html">serializeFileUrl</a></td><td>Builds a url for a single stored file — the write-side counterpart of <a href="./functions/parseFileUrl.html">parseFileUrl</a>.</td></tr><tr><td><a href="./functions/serializeGroupUrl.html">serializeGroupUrl</a></td><td>Builds a group root url, a group element url when <code>nth</code> is given, or the group&#39;s archive url when <code>archive</code> is — the write-side counterpart of <a href="./functions/parseGroupUrl.html">parseGroupUrl</a>, <a href="./functions/parseGroupElementUrl.html">parseGroupElementUrl</a> and <code>parseArchiveUrl</code>.</td></tr><tr><td><a href="./functions/serializeOperations.html">serializeOperations</a></td><td>Serializes operations into the <code>-/name/params/</code> directive chain (<code>&#39;&#39;</code> when the list is empty).</td></tr><tr><td><a href="./functions/serializeProxyUrl.html">serializeProxyUrl</a></td><td>Builds a delivery proxy url for a remote source — the write-side counterpart of <a href="./functions/parseProxyUrl.html">parseProxyUrl</a>. The source url is embedded verbatim and trails the operations, so it carries its own query string.</td></tr><tr><td><a href="./functions/tinyBuild.html">tinyBuild</a></td><td>Joins <a href="./interfaces/TinyFileUrl.html">TinyFileUrl</a> back into a url — the tiny counterpart of <code>serializeFileUrl</code>. Every field but <code>cdnBase</code> and <code>uuid</code> is optional, so this builds a url from scratch as readily as it rebuilds a parsed one. A trailing slash on <code>cdnBase</code> is trimmed, matching <code>serializeFileUrl</code>; nothing else is normalized.</td></tr><tr><td><a href="./functions/tinyParse.html">tinyParse</a></td><td>Cuts a single-file CDN url into <a href="./interfaces/TinyFileUrl.html">TinyFileUrl</a>, every field filled (<code>&#39;&#39;</code> when absent) — the tiny counterpart of <code>parseFileUrl</code>. Never throws and never validates: unknown operations and internal <code>@</code>-prefixed directives survive verbatim, and a secure-delivery token is kept in <code>search</code>.</td></tr><tr><td><a href="./functions/unsafeOperation.html">unsafeOperation</a></td><td>Escape hatch for an operation <a href="./type-aliases/OperationLiteral.html">OperationLiteral</a> cannot express — an <code>overlay</code> with a uuid, a <code>text</code> with arbitrary content, or a directive newer than this package.</td></tr></tbody></table>',9)])])}const f=t(d,[["render",o]]);export{u as __pageData,f as default};
